function farthestReach(commands: number[], obstacles: number[][]): number {
  const dx = [0, 1, 0, -1], dy = [1, 0, -1, 0];
  let x = 0, y = 0, dir = 0, best = 0;
  for (const c of commands) {
    if (c === -1) dir = (dir + 1) % 4;
    else if (c === -2) dir = (dir + 3) % 4;
    else {
      for (let s = 0; s < c; s++) {
        const nx = x + dx[dir], ny = y + dy[dir];
        if (obstacles.some(([ox, oy]) => ox === nx && oy === ny)) break;
        x = nx; y = ny;
        best = Math.max(best, x * x + y * y);
      }
    }
  }
  return best;
}

