    def farthestReach(self, commands: List[int], obstacles: List[List[int]]) -> int:
        dx, dy = [0, 1, 0, -1], [1, 0, -1, 0]
        x = y = d = best = 0
        for c in commands:
            if c == -1:
                d = (d + 1) % 4
            elif c == -2:
                d = (d + 3) % 4
            else:
                for _ in range(c):
                    nx, ny = x + dx[d], y + dy[d]
                    if [nx, ny] in obstacles:
                        break
                    x, y = nx, ny
                    best = max(best, x * x + y * y)
        return best

